/537.36 (KHTML, like Gecko) Chrome/146.0.0.0 Safari/537.36','2026-03-19 15:38:42','2026-03-19 15:38:42'),(789,NULL,'update','App\\Models\\RetributionClassification',9,'{\"updated_at\": \"2026-03-22T01:57:41.000000Z\", \"form_schema\": [{\"key\": \"sifat_pemasangan\", \"type\": \"select\", \"label\": \"Sifat Pemasangan\", \"options\": [{\"label\": \"Permanen (Video/Bill/Bando/Papan)\", \"value\": \"permanen\"}, {\"label\": \"Insidentil (Baliho/Spanduk/Kain)\", \"value\": \"insidentil\"}], \"required\": true}, {\"key\": \"jenis_reklame\", \"type\": \"select\", \"label\": \"Jenis Reklame\", \"options\": [{\"label\": \"Videotron / Megatron / LED\", \"value\": \"videotron\"}, {\"label\": \"Billboard / Baliho / Papan\", \"value\": \"billboard\"}, {\"label\": \"Papan / Pintu / Menempel\", \"value\": \"papan\"}, {\"label\": \"Spanduk / Banner / Kain\", \"value\": \"spanduk\"}, {\"label\": \"Selebaran / Brosur / Stiker\", \"value\": \"selebaran\"}, {\"label\": \"Reklame Berjalan / Kendaraan\", \"value\": \"kendaraan\"}, {\"label\": \"Reklame Suara\", \"value\": \"suara\"}, {\"label\": \"Reklame Film / Slide\", \"value\": \"film\"}], \"required\": true}, {\"key\": \"produk_khusus\", \"type\": \"select\", \"label\": \"Produk Khusus / Lokasi Khusus\", \"options\": [{\"label\": \"Umum (Tanpa Produk Rokok/Alkohol)\", \"value\": \"umum\"}, {\"label\": \"Produk Rokok / Minuman Beralkohol (110%)\", \"value\": \"rokok_alkohol\"}, {\"label\": \"Di Dalam Ruangan / Mall (50%)\", \"value\": \"mall_indoor\"}], \"required\": true}, {\"key\": \"kelas_jalan\", \"type\": \"select\", \"label\": \"Kelas Jalan (Zonasi)\", \"options\": [{\"label\": \"Kelas Jalan A (Sangat Strategis)\", \"value\": \"kelas_a\"}, {\"label\": \"Kelas Jalan B (Strategis)\", \"value\": \"kelas_b\"}, {\"label\": \"Kelas Jalan C (Biasa)\", \"value\": \"kelas_c\"}], \"required\": true}, {\"key\": \"panjang\", \"type\": \"number\", \"label\": \"Panjang Reklame (m)\", \"required\": true}, {\"key\": \"lebar\", \"type\": \"number\", \"label\": \"Lebar Reklame (m)\", \"required\": true}, {\"key\": \"jumlah_sisi\", \"type\": \"number\", \"label\": \"Jumlah Sisi Arah Pandang\", \"default_value\": 1}, {\"key\": \"jumlah_unit\", \"type\": \"number\", \"label\": \"Jumlah Unit / Lembar\", \"default_value\": 1}, {\"key\": \"durasi\", \"type\": \"number\", \"label\": \"Durasi (angka)\", \"default_value\": 1}, {\"key\": \"satuan_durasi\", \"type\": \"select\", \"label\": \"Satuan Durasi\", \"options\": [{\"label\": \"Tahun\", \"value\": \"tahun\"}, {\"label\": \"Bulan\", \"value\": \"bulan\"}, {\"label\": \"Minggu\", \"value\": \"minggu\"}, {\"label\": \"Hari\", \"value\": \"hari\"}, {\"label\": \"Menit\", \"value\": \"menit\"}], \"required\": true}, {\"key\": \"njopr_satuan\", \"type\": \"number\", \"label\": \"NJOPR Satuan (Rp/m2)\", \"required\": true}, {\"key\": \"nspr_satuan\", \"type\": \"number\", \"label\": \"NSPR Satuan (Zonasi) (Rp/m2)\", \"required\": true}], \"calculation_formula\": \"((njopr_satuan + nspr_satuan) * IF(panjang * lebar < 1, 1, panjang * lebar) * jumlah_sisi) * IF(produk_khusus == \\\"rokok_alkohol\\\", 1.1, IF(produk_khusus == \\\"mall_indoor\\\", 0.5, 1.0)) * 0.25 * jumlah_unit * durasi\"}','{\"updated_at\": \"2026-03-22 02:14:45\", \"form_schema\": \"[{\\\"key\\\":\\\"sifat_pemasangan\\\",\\\"type\\\":\\\"select\\\",\\\"label\\\":\\\"Sifat Pemasangan\\\",\\\"options\\\":[{\\\"label\\\":\\\"Permanen (Video\\\\/Bill\\\\/Bando\\\\/Papan)\\\",\\\"value\\\":\\\"permanen\\\"},{\\\"label\\\":\\\"Insidentil (Baliho\\\\/Spanduk\\\\/Kain)\\\",\\\"value\\\":\\\"insidentil\\\"}],\\\"required\\\":true},{\\\"key\\\":\\\"jenis_reklame\\\",\\\"type\\\":\\\"select\\\",\\\"label\\\":\\\"Jenis Reklame\\\",\\\"options\\\":[{\\\"label\\\":\\\"Videotron \\\\/ Megatron \\\\/ LED\\\",\\\"value\\\":\\\"videotron\\\"},{\\\"label\\\":\\\"Billboard \\\\/ Baliho \\\\/ Papan\\\",\\\"value\\\":\\\"billboard\\\"},{\\\"label\\\":\\\"Papan \\\\/ Pintu \\\\/ Menempel\\\",\\\"value\\\":\\\"papan\\\"},{\\\"label\\\":\\\"Spanduk \\\\/ Banner \\\\/ Kain\\\",\\\"value\\\":\\\"spanduk\\\"},{\\\"label\\\":\\\"Selebaran \\\\/ Brosur \\\\/ Stiker\\\",\\\"value\\\":\\\"selebaran\\\"},{\\\"label\\\":\\\"Reklame Berjalan \\\\/ Kendaraan\\\",\\\"value\\\":\\\"kendaraan\\\"},{\\\"label\\\":\\\"Reklame Suara\\\",\\\"value\\\":\\\"suara\\\"},{\\\"label\\\":\\\"Reklame Film \\\\/ Slide\\\",\\\"value\\\":\\\"film\\\"}],\\\"required\\\":true},{\\\"key\\\":\\\"kelas_jalan\\\",\\\"type\\\":\\\"select\\\",\\\"label\\\":\\\"Kelas Jalan (Zonasi)\\\",\\\"options\\\":[{\\\"label\\\":\\\"Kelas Jalan A (Sangat Strategis)\\\",\\\"value\\\":\\\"kelas_a\\\"},{\\\"label\\\":\\\"Kelas Jalan B (Strategis)\\\",\\\"value\\\":\\\"kelas_b\\\"},{\\\"label\\\":\\\"Kelas Jalan C (Biasa)\\\",\\\"value\\\":\\\"kelas_c\\\"}],\\\"required\\\":true},{\\\"key\\\":\\\"panjang\\\",\\\"type\\\":\\\"number\\\",\\\"label\\\":\\\"Panjang Reklame (m)\\\",\\\"required\\\":true},{\\\"key\\\":\\\"lebar\\\",\\\"type\\\":\\\"number\\\",\\\"label\\\":\\\"Lebar Reklame (m)\\\",\\\"required\\\":true},{\\\"key\\\":\\\"jumlah_sisi\\\",\\\"type\\\":\\\"number\\\",\\\"label\\\":\\\"Jumlah Sisi Arah Pandang\\\",\\\"default_value\\\":1},{\\\"key\\\":\\\"jumlah_unit\\\",\\\"type\\\":\\\"number\\\",\\\"label\\\":\\\"Jumlah Unit \\\\/ Lembar\\\",\\\"default_value\\\":1},{\\\"key\\\":\\\"durasi\\\",\\\"type\\\":\\\"number\\\",\\\"label\\\":\\\"Durasi (angka)\\\",\\\"default_value\\\":1},{\\\"key\\\":\\\"satuan_durasi\\\",\\\"type\\\":\\\"select\\\",\\\"label\\\":\\\"Satuan Durasi\\\",\\\"options\\\":[{\\\"label\\\":\\\"Tahun\\\",\\\"value\\\":\\\"tahun\\\"},{\\\"label\\\":\\\"Bulan\\\",\\\"value\\\":\\\"bulan\\\"},{\\\"label\\\":\\\"Minggu\\\",\\\"value\\\":\\\"minggu\\\"},{\\\"label\\\":\\\"Hari\\\",\\\"value\\\":\\\"hari\\\"},{\\\"label\\\":\\\"Menit\\\",\\\"value\\\":\\\"menit\\\"}],\\\"required\\\":true},{\\\"key\\\":\\\"njopr_satuan\\\",\\\"type\\\":\\\"number\\\",\\\"label\\\":\\\"NJOPR Satuan (Rp\\\\/m2)\\\",\\\"required\\\":true},{\\\"key\\\":\\\"nspr_satuan\\\",\\\"type\\\":\\\"number\\\",\\\"label\\\":\\\"NSPR Satuan (Zonasi) (Rp\\\\/m2)\\\",\\\"required\\\":true}]\", \"calculation_formula\": \"((njopr_satuan + nspr_satuan) * IF(panjang * lebar < 1, 1, panjang * lebar) * jumlah_sisi) * 0.25 * jumlah_unit * durasi\"}','127.0.0.1','Symfony','2026-03-21 18:14:45','2026-03-21 18:14:45');
