INSERT INTO `retribution_classifications` VALUES (1,4,8,'PBJT - Makan dan Minum',1,'PBJT-MNM','[{\"key\": \"omset_bulanan\", \"type\": \"number\", \"label\": \"Total Omzet Bulanan (Rp)\", \"required\": true}, {\"key\": \"jumlah_meja\", \"type\": \"number\", \"label\": \"Jumlah Meja\"}, {\"key\": \"kapasitas_kursi\", \"type\": \"number\", \"label\": \"Total Kapasitas Kursi\"}]','[{\"key\": \"nib_usaha\", \"name\": \"NIB / Izin Usaha\", \"required\": true}, {\"key\": \"foto_tempat_usaha\", \"name\": \"Foto Tempat Usaha\", \"required\": true}]','omzet * 0.10',NULL,NULL,'https://res.cloudinary.com/ddhgtgsed/image/upload/v1769703399/retribusi/mobile/icons/pasar.png','2026-03-01 21:13:28','2026-03-14 21:01:55'),(2,4,8,'PBJT - Tenaga Listrik',1,'PBJT-LIS','[{\"key\": \"omset_bulanan\", \"type\": \"number\", \"label\": \"Total Omzet Bulanan (Rp)\", \"required\": true}]','[{\"key\": \"nib_usaha\", \"name\": \"NIB / Izin Usaha\", \"required\": true}]','tagihan * 0.10',NULL,NULL,'https://res.cloudinary.com/ddhgtgsed/image/upload/v1769703395/retribusi/mobile/icons/internet.png','2026-03-01 21:13:28','2026-03-14 21:01:55'),(3,4,8,'PBJT - Jasa Perhotelan',1,'PBJT-HTL','[{\"key\": \"omset_kamar\", \"type\": \"number\", \"label\": \"Omzet Pemakaian Kamar (Rp)\", \"required\": true}, {\"key\": \"omset_lain\", \"type\": \"number\", \"label\": \"Omzet Lain-lain (Rp)\"}, {\"key\": \"jumlah_kamar\", \"type\": \"number\", \"label\": \"Total Jumlah Kamar\", \"required\": true}, {\"key\": \"tipe_hotel\", \"type\": \"select\", \"label\": \"Tipe Hotel\", \"options\": [{\"label\": \"Bintang 5\", \"value\": \"bintang_5\"}, {\"label\": \"Bintang 4\", \"value\": \"bintang_4\"}, {\"label\": \"Bintang 3\", \"value\": \"bintang_3\"}, {\"label\": \"Melati / Guest House\", \"value\": \"melati\"}]}]','[{\"key\": \"izin_tdup\", \"name\": \"Izin TDUP\", \"required\": true}, {\"key\": \"foto_bangunan_hotel\", \"name\": \"Foto Bangunan Hotel\", \"required\": true}]','omzet * 0.10',NULL,NULL,'https://res.cloudinary.com/ddhgtgsed/image/upload/v1769855470/retribusi/icons/tjhkxpabcvlhjegvnzyf.jpg','2026-03-01 21:13:28','2026-03-14 21:01:55'),(9,4,7,'Pajak Reklame',0,'REKLAME','[{\"key\": \"sifat_pemasangan\", \"type\": \"select\", \"label\": \"Sifat Pemasangan\", \"options\": [{\"label\": \"Permanen (Video/Bill/Bando/Papan)\", \"value\": \"permanen\"}, {\"label\": \"Insidentil (Baliho/Spanduk/Kain)\", \"value\": \"insidentil\"}], \"required\": true}, {\"key\": \"jenis_reklame\", \"type\": \"select\", \"label\": \"Jenis Reklame\", \"options\": [{\"label\": \"Videotron / Megatron / LED\", \"value\": \"videotron\"}, {\"label\": \"Billboard / Baliho / Papan\", \"value\": \"billboard\"}, {\"label\": \"Papan / Pintu / Menempel\", \"value\": \"papan\"}, {\"label\": \"Spanduk / Banner / Kain\", \"value\": \"spanduk\"}, {\"label\": \"Selebaran / Brosur / Stiker\", \"value\": \"selebaran\"}, {\"label\": \"Reklame Berjalan / Kendaraan\", \"value\": \"kendaraan\"}, {\"label\": \"Reklame Suara\", \"value\": \"suara\"}, {\"label\": \"Reklame Film / Slide\", \"value\": \"film\"}], \"required\": true}, {\"key\": \"kelas_jalan\", \"type\": \"select\", \"label\": \"Kelas Jalan (Zonasi)\", \"options\": [{\"label\": \"Kelas Jalan A (Sangat Strategis)\", \"value\": \"kelas_a\"}, {\"label\": \"Kelas Jalan B (Strategis)\", \"value\": \"kelas_b\"}, {\"label\": \"Kelas Jalan C (Biasa)\", \"value\": \"kelas_c\"}], \"required\": true}, {\"key\": \"panjang\", \"type\": \"number\", \"label\": \"Panjang Reklame (m)\", \"required\": true}, {\"key\": \"lebar\", \"type\": \"number\", \"label\": \"Lebar Reklame (m)\", \"required\": true}, {\"key\": \"jumlah_sisi\", \"type\": \"number\", \"label\": \"Jumlah Sisi Arah Pandang\", \"default_value\": 1}, {\"key\": \"jumlah_unit\", \"type\": \"number\", \"label\": \"Jumlah Unit / Lembar\", \"default_value\": 1}, {\"key\": \"durasi\", \"type\": \"number\", \"label\": \"Durasi (angka)\", \"default_value\": 1}, {\"key\": \"satuan_durasi\", \"type\": \"select\", \"label\": \"Satuan Durasi\", \"options\": [{\"label\": \"Tahun\", \"value\": \"tahun\"}, {\"label\": \"Bulan\", \"value\": \"bulan\"}, {\"label\": \"Minggu\", \"value\": \"minggu\"}, {\"label\": \"Hari\", \"value\": \"hari\"}, {\"label\": \"Menit\", \"value\": \"menit\"}], \"required\": true}, {\"key\": \"njopr_satuan\", \"type\": \"number\", \"label\": \"NJOPR Satuan (Rp/m2)\", \"required\": true}, {\"key\": \"nspr_satuan\", \"type\": \"number\", \"label\": \"NSPR Satuan (Zonasi) (Rp/m2)\", \"required\": true}]','[{\"key\": \"desain_reklame\", \"name\": \"Desain Reklame\", \"required\": true}, {\"key\": \"ipr_dokumen\", \"name\": \"Izin Penyelenggaraan Reklame (IPR)\", \"required\": true}, {\"key\": \"foto_titik_reklame\", \"name\": \"Foto Lokasi Titik Reklame\", \"required\": true}]','((njopr_satuan + nspr_satuan) * IF(panjang * lebar < 1, 1, panjang * lebar) * jumlah_sisi) * 0.25 * jumlah_unit * durasi',NULL,NULL,'https://res.cloudinary.com/ddhgtgsed/image/upload/v1769855480/retribusi/icons/airqm7ydazqqpsqezlrv.jpg','2026-03-01 21:13:29','2026-03-21 18:14:45'),(10,4,7,'Pajak MBLB',1,'MBLB','[{\"key\": \"volume_m3\", \"type\": \"number\", \"label\": \"Volume Pengambilan (m3)\", \"required\": true}, {\"key\": \"jenis_material\", \"type\": \"select\", \"label\": \"Jenis Material\", \"options\": [{\"label\": \"Pasir\", \"value\": \"pasir\"}, {\"label\": \"Batu\", \"value\": \"batu\"}, {\"label\": \"Tanah Timbun\", \"value\": \"tanah\"}]}]','[{\"key\": \"izin_sipb\", \"name\": \"Izin SIPB / IUP\", \"required\": true}, {\"key\": \"laporan_produksi\", \"name\": \"Laporan Produksi Bulanan\", \"required\": true}]','(volume * harga) * 0.15',NULL,NULL,'https://res.cloudinary.com/ddhgtgsed/image/upload/v1769855474/retribusi/icons/pl1ag8vgja8jwzabaavc.jpg','2026-03-01 21:13:29','2026-03-14 21:01:55'),(13,4,7,'BPHTB',0,'BPHTB','[{\"key\": \"omzet\", \"type\": \"number\", \"label\": \"Total Omzet/Nilai\", \"required\": true}]','[{\"key\": \"foto_lokasi_open_kamera\", \"label\"